package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Four unchanged API53 methods passed Salesforce Wave95.
func TestRunAliasURLContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeUrlCatch53.cls"), "@IsTest private class GladeUrlCatch53 {\n    public static String getInternalUrlPath(String url) {\n        try {\n\n            String internalUrl = '';\n\n            if (url.startsWith('/')) {\n                internalUrl = '/' + url.replaceFirst('/+', '');\n            } else {\n                internalUrl = new Url(url).getPath();\n            }\n\n            return internalUrl;\n\n        } catch(Exception ex) {\n\n            return null;\n        }\n    }\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\nprivate static void finish(String method,List<Object> rows){String text=JSON.serialize(new Map<String,Object>{'method'=>method,'rows'=>rows,'done'=>true});System.assert(text.length()<2900,method+': complete observation bound');Map<String,String> expectedByMethod=new Map<String,String>{'directPicklistAliasDml'=>'{\"done\":true,\"rows\":[{\"field\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: GladeAliasRecord53__c.State__c\",\"type\":\"System.SObjectException\"},\"alias\":{\"value\":\"Owned Label\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"directPicklistAliasDml\"}','unaliasedParentDmlControl'=>'{\"done\":true,\"rows\":[{\"parentName\":{\"value\":\"Owned Probe Label\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"unaliasedParentDmlControl\"}','constructorExceptionObservation'=>'{\"done\":true,\"rows\":[{\"continued\":true,\"message\":\"no protocol: www.salesforce.com\",\"type\":\"System.StringException\",\"caught\":true,\"input\":\"www.salesforce.com\"},{\"continued\":true,\"caught\":false,\"path\":\"/testPath\",\"input\":\"https://salesforce.com/testPath\"}],\"method\":\"constructorExceptionObservation\"}'};System.assert(expectedByMethod.containsKey(method),method+': expected case');assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(text),method);}\n\n@IsTest static void originalWrapperContracts(){\nSystem.assertEquals(null,getInternalUrlPath('www.salesforce.com'),'original invalid URL returns null through catch');\nSystem.assertEquals('/testPath',getInternalUrlPath('https://salesforce.com/testPath'),'original absolute URL path');\nSystem.assertEquals('/testPath',getInternalUrlPath('//testPath'),'original internal URL sanitation');\n}\n@IsTest static void constructorExceptionObservation(){List<Object> rows=new List<Object>();for(String input:new List<String>{'www.salesforce.com','https://salesforce.com/testPath'}){Map<String,Object> row=new Map<String,Object>{'input'=>input};try{Url value=new Url(input);row.put('path',value.getPath());row.put('caught',false);}catch(Exception e){row.put('caught',true);row.put('type',e.getTypeName());row.put('message',e.getMessage());}row.put('continued',true);rows.add(row);}System.assertEquals(2,rows.size(),'both constructor attempts completed');finish('constructorExceptionObservation',rows);}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeUrlCatch53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAliasDml53.cls"), "@IsTest private class GladeAliasDml53 {\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\nprivate static void finish(String method,List<Object> rows){String text=JSON.serialize(new Map<String,Object>{'method'=>method,'rows'=>rows,'done'=>true});System.assert(text.length()<2900,method+': complete observation bound');Map<String,String> expectedByMethod=new Map<String,String>{'directPicklistAliasDml'=>'{\"done\":true,\"rows\":[{\"field\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: GladeAliasRecord53__c.State__c\",\"type\":\"System.SObjectException\"},\"alias\":{\"value\":\"Owned Label\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"directPicklistAliasDml\"}','unaliasedParentDmlControl'=>'{\"done\":true,\"rows\":[{\"parentName\":{\"value\":\"Owned Probe Label\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"unaliasedParentDmlControl\"}','constructorExceptionObservation'=>'{\"done\":true,\"rows\":[{\"continued\":true,\"message\":\"no protocol: www.salesforce.com\",\"type\":\"System.StringException\",\"caught\":true,\"input\":\"www.salesforce.com\"},{\"continued\":true,\"caught\":false,\"path\":\"/testPath\",\"input\":\"https://salesforce.com/testPath\"}],\"method\":\"constructorExceptionObservation\"}'};System.assert(expectedByMethod.containsKey(method),method+': expected case');assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(text),method);}\n\nprivate static Object read(SObject row,String field){try{return new Map<String,Object>{'value'=>row.get(field)};}catch(Exception e){return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}}\nprivate static Object readParent(SObject row,String relationship,String field){try{return read(row.getSObject(relationship),field);}catch(Exception e){return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}}\nprivate static GladeAliasRecord53__c setup(){RecordType kind=[SELECT Id FROM RecordType WHERE SObjectType='GladeAliasRecord53__c' AND DeveloperName='Owned_Probe'];GladeAliasRecord53__c row=new GladeAliasRecord53__c(Name='before',State__c='Owned',RecordTypeId=kind.Id);insert row;return row;}\nprivate static void updateAndObserve(List<Object> rows,GladeAliasRecord53__c selected){selected.Name='after';Map<String,Object> change=new Map<String,Object>{'phase'=>'update'};try{update selected;change.put('success',true);}catch(DmlException e){change.put('success',false);change.put('type',e.getTypeName());change.put('status',String.valueOf(e.getDmlStatusCode(0)));change.put('message',e.getDmlMessage(0));change.put('fields',e.getDmlFieldNames(0));}rows.add(change);GladeAliasRecord53__c stored=[SELECT Name,State__c FROM GladeAliasRecord53__c WHERE Id=:selected.Id];rows.add(new Map<String,Object>{'phase'=>'stored','name'=>stored.Name,'state'=>stored.State__c,'count'=>[SELECT COUNT() FROM GladeAliasRecord53__c]});}\n@IsTest static void directPicklistAliasDml(){GladeAliasRecord53__c input=setup();List<Object> rows=new List<Object>();GladeAliasRecord53__c selected=[SELECT Id,Name,toLabel(State__c) StateLabel FROM GladeAliasRecord53__c WHERE Id=:input.Id];rows.add(new Map<String,Object>{'phase'=>'projection','alias'=>read(selected,'StateLabel'),'field'=>read(selected,'State__c')});updateAndObserve(rows,selected);finish('directPicklistAliasDml',rows);}\n@IsTest static void unaliasedParentDmlControl(){GladeAliasRecord53__c input=setup();List<Object> rows=new List<Object>();GladeAliasRecord53__c selected=[SELECT Id,Name,toLabel(RecordType.Name) FROM GladeAliasRecord53__c WHERE Id=:input.Id];rows.add(new Map<String,Object>{'phase'=>'projection','parentName'=>readParent(selected,'RecordType','Name')});updateAndObserve(rows,selected);finish('unaliasedParentDmlControl',rows);}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAliasDml53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/GladeAliasRecord53__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Glade Alias Record</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>Glade Alias Records</pluralLabel><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/fields/State__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>State__c</fullName><label>State</label><required>false</required><type>Picklist</type><valueSet><restricted>true</restricted><valueSetDefinition><sorted>false</sorted><value><fullName>Owned</fullName><default>true</default><label>Owned Label</label></value></valueSetDefinition></valueSet></CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/recordTypes/Owned_Probe.recordType-meta.xml"), "<RecordType xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Owned_Probe</fullName><active>true</active><label>Owned Probe Label</label><picklistValues><picklist>State__c</picklist><values><fullName>Owned</fullName><default>true</default></values></picklistValues></RecordType>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("alias and URL contracts failed: %s", data)
	}
}
